const int MOD = 998244353;

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

struct Matrix {
    vector<vector<long long>> data;
    int n;

    Matrix(int size = 0, bool identity = false) : n(size) {
        data.assign(size, vector<long long>(size, 0));
        if (identity) {
            for (int i = 0; i < size; i++)
                data[i][i] = 1;
        }
    }

    Matrix operator*(const Matrix& other) const {
        Matrix result(n);
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (data[i][k] == 0) continue;
