            }
        }
        return result;
    }

    Matrix operator^(long long exp) const {
        Matrix result(n, true);
        Matrix base = *this;
        while (exp > 0) {
            if (exp & 1)
                result = result * base;
            base = base * base;
            exp >>= 1;
        }
        return result;
    }
};

