struct Matrix {
    int n;
    vector<vector<long long>> a;

    Matrix(int n = 0) : n(n), a(n, vector<long long>(n, 0)) {}

    Matrix operator*(const Matrix& other) const {
        Matrix res(n);
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    res.a[i][j] = (res.a[i][j] + a[i][k] * other.a[k][j]) % MOD;
                }
            }
        }
        return res;
    }

    Matrix power(long long exp) {
        Matrix result(n);
        for (int i = 0; i < n; i++) result.a[i][i] = 1;
        Matrix base = *this;
        while (exp > 0) {
            if (exp & 1) result = result * base;
            base = base * base;
            exp >>= 1;
        }
        return result;
    }
};

