const int MOD = 998244353;

struct Matrix {
    vector<vector<long long>> a;
    int n;

    Matrix(int _n = 0, bool ident = false) : n(_n) {
        a.assign(n, vector<long long>(n, 0));
        if (ident) {
            for (int i = 0; i < n; i++) a[i][i] = 1;
        }
    }

    Matrix operator*(const Matrix& other) const {
        Matrix res(n);
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    res.a[i][j] = (res.a[i][j] + a[i][k] * other.a[k][j]) % MOD;
                }
            }
        }
        return res;
    }

    Matrix pow(long long p) {
        Matrix res(n, true);
        Matrix base = *this;
        while (p) {
            if (p & 1) res = res * base;
            base = base * base;
            p >>= 1;
        }
        return res;
    }
};

